<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { User, Plus, Connection, Lock } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { useWorkspace } from '../store'
import { request, post, showError } from '../api'
const ws = useWorkspace(), users = ref<{ id: number; username: string; is_admin: boolean | number; disabled: boolean | number; created_at: string }[]>([]), loading = ref(false), dialog = ref(false), username = ref(''), password = ref(''), isAdmin = ref(false), saving = ref(false)
function formatDate(value: number | string) { const numeric = Number(value); const date = Number.isFinite(numeric) ? new Date(numeric * 1000) : new Date(value); return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Shanghai' }).format(date) }
async function load() { loading.value = true; try { users.value = await request('/admin/users') } catch (e) { showError(e) } finally { loading.value = false } }
async function create() { if (!username.value.trim() || password.value.length < 12) return; saving.value = true; try { await post('/admin/users', { username: username.value.trim(), password: password.value, is_admin: isAdmin.value }); password.value = ''; username.value = ''; isAdmin.value = false; dialog.value = false; await load(); ElMessage.success('账号已创建，请通过可信方式告知成员') } catch (e) { showError(e) } finally { saving.value = false } }
onMounted(load)
</script>
<template><div class="admin-page"><header class="page-heading"><div><div class="eyebrow">WORKSPACE ADMINISTRATION</div><h1>让课题组有序协作</h1><p>管理成员账号，查看当前运行配置。</p></div><span class="subtle-badge"><el-icon><Lock/></el-icon>仅管理员可见</span></header><section class="settings-section"><div class="settings-heading"><div><h2><el-icon><User/></el-icon>成员账号</h2><p>成员拥有独立会话与私有资料，共享库权限由库所有者分配。</p></div><el-button type="primary" @click="dialog = true"><el-icon><Plus/></el-icon>创建账号</el-button></div><el-table :data="users" v-loading="loading" empty-text="暂无账号"><el-table-column prop="username" label="账号"/><el-table-column label="角色"><template #default="{ row }"><span :class="['evidence-badge', row.is_admin ? 'abstract' : 'metadata']">{{ row.is_admin ? '管理员' : '课题组成员' }}</span></template></el-table-column><el-table-column label="状态"><template #default="{ row }"><span class="document-status" :class="{ ready: !row.disabled }"><span class="tiny-dot"></span>{{ row.disabled ? '已停用' : '可使用' }}</span></template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="{ row }">{{ formatDate(row.created_at) }}</template></el-table-column></el-table></section><section class="settings-section"><div class="settings-heading"><div><h2><el-icon><Connection/></el-icon>当前连接配置</h2><p>这里只显示实际运行状态，不显示密钥。</p></div></div><div class="connection-grid"><div><span>文本模型供应商</span><strong>{{ ws.config?.chat_provider === 'openai' ? 'OpenAI' : ws.config?.chat_provider === 'dashscope' ? '阿里云百炼' : ws.config?.chat_provider || '未获取' }}</strong><small>{{ ws.config?.model_configured ? '已配置凭据' : '尚未配置凭据' }} · 不代表已通过调用验证</small></div><div><span>嵌入模型供应商</span><strong>{{ ws.config?.embedding_provider === 'openai' ? 'OpenAI' : ws.config?.embedding_provider === 'dashscope' ? '阿里云百炼' : ws.config?.embedding_provider || '未获取' }}</strong><small>向量索引按配置使用对应供应商</small></div><div><span>开放学术检索</span><strong>{{ ws.config?.external_search_enabled ? '已启用' : '已关闭' }}</strong><small>只有用户提交检索时才访问外部索引</small></div><div><span>会话原文保留</span><strong>{{ ws.config?.temporary_retention_days || 7 }} 天</strong><small>正式文献库独立保留</small></div></div><p class="settings-note">供应商、密钥与预算由部署配置管理；此页面不修改运行配置。</p></section><el-dialog v-model="dialog" title="创建课题组账号" width="460px" @closed="password = ''"><el-form label-position="top" @submit.prevent="create"><el-form-item label="用户名"><el-input v-model="username" autocomplete="off" maxlength="64" placeholder="成员用户名"/></el-form-item><el-form-item label="初始密码"><el-input v-model="password" type="password" show-password autocomplete="new-password" maxlength="256" placeholder="至少 12 个字符"/></el-form-item><el-checkbox v-model="isAdmin">授予管理员权限</el-checkbox><p class="field-note">请为每位成员创建独立账号，并通过可信方式传递初始密码。</p></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!username.trim() || password.length < 12" @click="create">创建账号</el-button></template></el-dialog></div></template>
